  AND (
    toLower(league.name) CONTAINS 'american league'
    OR toLower(league.name) CONTAINS 'national league'
    OR any(alias IN coalesce(league.aliases, []) WHERE toLower(alias) CONTAINS 'american league' OR toLower(alias) CONTAINS 'national league')
  )
WITH team, league, p, CASE WHEN length(p) = 2 THEN nodes(p)[1] ELSE null END AS division
RETURN DISTINCT team.name AS team, league.name AS league, division.name AS division, [r IN relationships(p) | type(r)] AS connections
LIMIT 10
