Cypher query: MATCH (n:__Entity__)-[r]-(m:__Entity__)
WHERE (toLower(n.name) CONTAINS 'yadava' OR toLower(n.name) CONTAINS 'golla' OR any(alias IN coalesce(n.aliases, []) WHERE toLower(alias) CONTAINS 'yadava' OR toLower(alias) CONTAINS 'golla'))
RETURN DISTINCT n.name AS entity, type(r) AS relationship, m.name AS related, r.relationship AS relationship_detail, r.relation AS relation, r.fact AS fact, r.context AS context
LIMIT 10
