Cypher query: MATCH (series:Work)
WHERE toLower(series.name) CONTAINS 'diary of a wimpy kid'
   OR any(alias IN coalesce(series.aliases, []) WHERE toLower(alias) CONTAINS 'diary of a wimpy kid')
CALL {
  WITH series
  OPTIONAL MATCH (book:Work)-[:PART_OF]->(series)
  RETURN collect(DISTINCT book.name) AS titles
}
CALL {
  WITH series
  OPTIONAL MATCH (p:Person)-[r:CREATED|RELATED_TO|PARTICIPATED_IN]-(target:Work)
  WHERE (toLower(p.name) CONTAINS 'jeff kinney'
         OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'jeff kinney'))
    AND (target = series OR EXISTS { MATCH (target)-[:PART_OF]->(series) })
  RETURN collect(DISTINCT p.name) AS connected_people,
         collect(DISTINCT type(r)) AS relationships,
         collect(DISTINCT target.name) AS linked_titles
}
RETURN series.name AS series, size(titles) AS number_of_main_books, titles,
       connected_people, relationships, linked_titles
LIMIT 10
