Cypher query: MATCH (oh:__Entity__), (ev:Event)
WHERE (toLower(oh.name) CONTAINS 'ohio state' OR any(alias IN coalesce(oh.aliases, []) WHERE toLower(alias) CONTAINS 'ohio state'))
  AND (toLower(ev.name) CONTAINS 'volleyball' OR any(alias IN coalesce(ev.aliases, []) WHERE toLower(alias) CONTAINS 'volleyball'))
  AND (toLower(ev.name) CONTAINS '2017' OR toLower(coalesce(ev.date, '')) CONTAINS '2017' OR any(alias IN coalesce(ev.aliases, []) WHERE toLower(alias) CONTAINS '2017'))
OPTIONAL MATCH (ev)-[r]-(participant:__Entity__)
WITH oh, ev, collect(DISTINCT CASE WHEN participant IS NULL THEN null ELSE {name: participant.name, relationship: type(r), result: r.result, outcome: r.outcome} END) AS event_connections
OPTIONAL MATCH (oh)-[ro]-(connection:__Entity__)
RETURN ev.name AS championship, ev.date AS date, event_connections, oh.name AS OhioState, collect(DISTINCT CASE WHEN connection IS NULL THEN null ELSE {name: connection.name, relationship: type(ro)} END) AS OhioState_connections
LIMIT 10
